using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using PawPuff.Data;
namespace PawPuff.Controllers;
[Authorize(Roles="Admin")] public class AdminController(ShopDbContext db):Controller { public async Task<IActionResult> Index(){ViewBag.ProductCount=await db.Products.CountAsync(p=>p.IsActive);ViewBag.OrderCount=await db.Orders.CountAsync();ViewBag.Revenue=await db.Orders.Where(o=>o.Status!="Cancelled").SumAsync(o=>(decimal?)o.Total)??0;ViewBag.Users=await db.Users.CountAsync();return View(await db.Orders.Include(o=>o.Items).OrderByDescending(o=>o.CreatedAt).Take(20).ToListAsync());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> UpdateStatus(int id,string status){var allowed=new[]{"Pending","Shipped","Completed","Cancelled","Paid (Demo)"};var order=await db.Orders.FindAsync(id);if(order!=null&&allowed.Contains(status)){order.Status=status;await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
